//  A --- B
//   \   /
//    \ /
//     C --- D
string[] namen = { "A", "B", "C", "D" };
int[,] m = new int[4, 4];

void Verbinde(int i, int j)
{
    m[i, j] = 1;
    m[j, i] = 1;   // ungerichtet!
}
Verbinde(0, 1); Verbinde(0, 2);
Verbinde(1, 2); Verbinde(2, 3);

//    A B C D
// A: 0 1 1 0
// B: 1 0 1 0
// C: 1 1 0 1
// D: 0 0 1 0

int grad = 0;
for (int j = 0; j < 4; j++)
    grad += m[2, j];
Console.WriteLine($"Grad C: {grad}");
// Grad C: 3

var netz =
    new Dictionary<string, List<string>>();

void Kante(string a, string b)
{
    if (!netz.ContainsKey(a))
        netz[a] = new List<string>();
    if (!netz.ContainsKey(b))
        netz[b] = new List<string>();
    netz[a].Add(b);
    netz[b].Add(a);
}

Kante("Bahnhof", "Hauptplatz");
Kante("Bahnhof", "Schule");
Kante("Hauptplatz", "Schule");
Kante("Hauptplatz", "Spital");
Kante("Schule", "Freibad");

foreach (var (st, nb) in netz)
    Console.WriteLine(
        $"{st}: {string.Join(", ", nb)}");
// Bahnhof: Hauptplatz, Schule
// Hauptplatz: Bahnhof, Schule, Spital
// Schule: Bahnhof, Hauptplatz, Freibad
// Spital: Hauptplatz
// Freibad: Schule

var strassen = new Dictionary<string,
    List<(string Ziel, int Km)>>
{
    ["A"] = new() { ("B", 7), ("C", 3) },
};

foreach (var (ziel, km) in strassen["A"])
    Console.WriteLine($"A -> {ziel}: {km} km");
// A -> B: 7 km
// A -> C: 3 km

